package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"sync"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type RateLimiter struct {
	mu       sync.Mutex
	tokens   int
	max      int
	refillAt time.Time
}

func NewRateLimiter(max int) *RateLimiter {
	return &RateLimiter{tokens: max, max: max, refillAt: time.Now().Add(time.Second)}
}

func (r *RateLimiter) Allow() bool {
	r.mu.Lock()
	defer r.mu.Unlock()
	if time.Now().After(r.refillAt) {
		r.tokens = r.max
		r.refillAt = time.Now().Add(time.Second)
	}
	if r.tokens > 0 {
		r.tokens--
		return true
	}
	return false
}

type Message struct {
	ID      string          `json:"id"`
	Action  string          `json:"action"`
	Payload json.RawMessage `json:"payload"`
	Retries int             `json:"retries"`
}

type UserLookup struct {
	Username string `json:"username"`
	Role     string `json:"role"`
}

type QueryBuilder struct {
	collection *mongo.Collection
}

func (qb *QueryBuilder) BuildFilter(lookup UserLookup) bson.M {
	filter := bson.M{}
	if lookup.Username != "" {
		filter["username"] = lookup.Username
	}
	if lookup.Role != "" {
		filter["role"] = lookup.Role
	}
	return filter
}

func (qb *QueryBuilder) Execute(ctx context.Context, filter bson.M) (*mongo.Cursor, error) {
	return qb.collection.Find(ctx, filter)
}

type MessageConsumer struct {
	queue   chan Message
	limiter *RateLimiter
	qb      *QueryBuilder
	maxRetry int
}

func NewMessageConsumer(col *mongo.Collection) *MessageConsumer {
	return &MessageConsumer{
		queue:    make(chan Message, 100),
		limiter:  NewRateLimiter(50),
		qb:       &QueryBuilder{collection: col},
		maxRetry: 3,
	}
}

func (mc *MessageConsumer) processLookup(ctx context.Context, msg Message) error {
	var lookup UserLookup
	if err := json.Unmarshal(msg.Payload, &lookup); err != nil {
		return fmt.Errorf("unmarshal payload: %w", err)
	}
	filter := mc.qb.BuildFilter(lookup)
	cursor, err := mc.qb.Execute(ctx, filter)
	if err != nil {
		return fmt.Errorf("query execution: %w", err)
	}
	defer cursor.Close(ctx)
	var results []bson.M
	if err := cursor.All(ctx, &results); err != nil {
		return fmt.Errorf("cursor read: %w", err)
	}
	log.Printf("Found %d results for lookup", len(results))
	return nil
}

func (mc *MessageConsumer) processRawQuery(ctx context.Context, msg Message) error {
	var rawFilter map[string]interface{}
	if err := json.Unmarshal(msg.Payload, &rawFilter); err != nil {
		return fmt.Errorf("unmarshal raw filter: %w", err)
	}
	sanitized := mc.sanitizeFilter(rawFilter)
	cursor, err := mc.qb.collection.Find(ctx, sanitized)
	if err != nil {
		return fmt.Errorf("raw query execution: %w", err)
	}
	defer cursor.Close(ctx)
	var results []bson.M
	if err := cursor.All(ctx, &results); err != nil {
		return fmt.Errorf("cursor read: %w", err)
	}
	log.Printf("Raw query returned %d results", len(results))
	return nil
}

func (mc *MessageConsumer) sanitizeFilter(input map[string]interface{}) bson.M {
	result := bson.M{}
	allowedFields := map[string]bool{"username": true, "role": true, "email": true, "status": true}
	for key, value := range input {
		if !allowedFields[key] {
			continue
		}
		result[key] = value
	}
	return result
}

func (mc *MessageConsumer) handleMessage(ctx context.Context, msg Message) error {
	switch msg.Action {
	case "lookup":
		return mc.processLookup(ctx, msg)
	case "query":
		return mc.processRawQuery(ctx, msg)
	default:
		return fmt.Errorf("unknown action: %s", msg.Action)
	}
}

func (mc *MessageConsumer) retryWithBackoff(ctx context.Context, msg Message) {
	for msg.Retries < mc.maxRetry {
		if !mc.limiter.Allow() {
			time.Sleep(100 * time.Millisecond)
			continue
		}
		err := mc.handleMessage(ctx, msg)
		if err == nil {
			return
		}
		msg.Retries++
		backoff := time.Duration(msg.Retries*msg.Retries) * 100 * time.Millisecond
		log.Printf("Retry %d for message %s: %v", msg.Retries, msg.ID, err)
		time.Sleep(backoff)
	}
	log.Printf("Message %s failed after %d retries", msg.ID, mc.maxRetry)
}

func (mc *MessageConsumer) Start(ctx context.Context) {
	for i := 0; i < 4; i++ {
		go func() {
			for msg := range mc.queue {
				mc.retryWithBackoff(ctx, msg)
			}
		}()
	}
}

func main() {
	client, err := mongo.Connect(context.Background(), options.Client().ApplyURI("mongodb://localhost:27017"))
	if err != nil {
		log.Fatal(err)
	}
	col := client.Database("app").Collection("users")
	consumer := NewMessageConsumer(col)
	ctx := context.Background()
	consumer.Start(ctx)
	select {}
}
